import{_ as s,c as a,d as t,o as p}from"./app-F_ELCBVL.js";const e={};function o(c,n){return p(),a("div",null,[...n[0]||(n[0]=[t(`<h1 id="rushwind-admin-—-多租户行级隔离与租户回收站-viewer-三态、repo-shell-与全域级联清除" tabindex="-1"><a class="header-anchor" href="#rushwind-admin-—-多租户行级隔离与租户回收站-viewer-三态、repo-shell-与全域级联清除"><span>RushWind Admin — 多租户行级隔离与租户回收站：Viewer 三态、repo_shell! 与全域级联清除</span></a></h1><blockquote><p>本文回答一个问题：<strong>一个列表查询怎么做到「想查出别家租户的行都漏不掉」？租户被删之后数据去哪了、恢复时凭什么不撞名、彻底清除时怎么不留下孤儿行？</strong></p></blockquote><p>多租户系统最怕的不是没有隔离，而是&quot;靠每个开发者记得加租户条件&quot;的隔离——新人一个 <code>find_by_id</code> 没带谓词，别家的数据就顺着接口流出去，而且没有人知道。<a href="https://github.com/tx7do/rushwind-admin" target="_blank" rel="noopener noreferrer">RushWind Admin</a> 把隔离做成两层结构：HTTP 门负责&quot;这个租户能不能用这个接口&quot;，数据层谓词负责&quot;这个查询能不能看见那行数据&quot;。删除则更进一步——<strong>delete 不是删除，是停车</strong>。本文把这两层和一条回收站链路全部拆开。</p><hr><h2 id="一、两道闸-http-门与数据层谓词" tabindex="-1"><a class="header-anchor" href="#一、两道闸-http-门与数据层谓词"><span>一、两道闸：HTTP 门与数据层谓词</span></a></h2><p>先看官方教程里对这套分层的定义（<code>docs/tutorial/06</code>）：</p><blockquote><p><strong>两层都过才有数据。只懂其中一层就会把&quot;接口 403&quot;和&quot;列表为空&quot;混为一谈：接口 403 是 HTTP 闸拒绝（租户没这个模块的套餐），列表为空是数据层谓词把别家的行滤掉了——同一次请求只撞其一。</strong></p></blockquote><p>这句话是全篇的地图。排障时先分清撞的是哪道闸，再去对应章节找机制。</p><h2 id="二、http-门-租户阶段夹在认证与授权之间" tabindex="-1"><a class="header-anchor" href="#二、http-门-租户阶段夹在认证与授权之间"><span>二、HTTP 门：租户阶段夹在认证与授权之间</span></a></h2><p>门在 wire 上的顺序是固定的：<strong>认证</strong>（JWT RS256 验签 + Redis 会话检查，一次调用完成，401）→ <strong>租户检查</strong>（403）→ <strong>授权评估</strong>（403）→ <strong>放行注入 claims</strong>。租户阶段是中间那道，它对每个租户请求跑一串有明确先后顺序的失败语义，代码里的自述（<code>backend/apps/admin/src/admin/authorizer.rs</code>）：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">/// The tenant access checks behind the gate&#39;s tenant stage. The</span></span>
<span class="line"><span class="token comment">/// reference semantics, in order: unknown tenant → \`access denied\`;</span></span>
<span class="line"><span class="token comment">/// status off \`ON\` → \`tenant is not active\`; expired under a</span></span>
<span class="line"><span class="token comment">/// \`READONLY\` plan → writes denied (\`tenant is read-only due to</span></span>
<span class="line"><span class="token comment">/// expiry\`); the route unregistered in \`sys_apis\` → fail-closed</span></span>
<span class="line"><span class="token comment">/// \`access denied\`; unclassified business module → \`module not</span></span>
<span class="line"><span class="token comment">/// allowed\`; a tenant without a plan → \`no subscription plan\`; a plan</span></span>
<span class="line"><span class="token comment">/// with no whitelisted module → \`tenant plan has no whitelisted</span></span>
<span class="line"><span class="token comment">/// modules\`; a module outside the whitelist → \`module not allowed\`.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>逐条翻译：租户不存在拒绝、停用拒绝、<strong>到期只读（写拒读通）</strong>、然后是这条链上最有性格的一条——<strong>fail-closed 的接口表校验</strong>：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/authorizer.rs</span></span>
<span class="line"><span class="token comment">// 3. The route&#39;s business module; an unregistered route cannot</span></span>
<span class="line"><span class="token comment">// be classified and fails closed.</span></span>
<span class="line"><span class="token keyword">let</span> api <span class="token operator">=</span> <span class="token namespace">sys_apis<span class="token punctuation">::</span></span><span class="token class-name">Entity</span><span class="token punctuation">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token class-name">Condition</span><span class="token punctuation">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token namespace">sys_apis<span class="token punctuation">::</span></span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">Path</span><span class="token punctuation">.</span><span class="token function">eq</span><span class="token punctuation">(</span>path<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token namespace">sys_apis<span class="token punctuation">::</span></span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">Method</span><span class="token punctuation">.</span><span class="token function">eq</span><span class="token punctuation">(</span>method<span class="token punctuation">.</span><span class="token function">to_uppercase</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">one</span><span class="token punctuation">(</span>db<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token keyword">await</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">map_err</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>_<span class="token closure-punctuation punctuation">|</span></span> <span class="token function">denied</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token operator">?</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ok_or_else</span><span class="token punctuation">(</span>denied<span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> module <span class="token operator">=</span> api<span class="token punctuation">.</span>business_module<span class="token punctuation">.</span><span class="token function">clone</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">unwrap_or_default</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">if</span> module<span class="token punctuation">.</span><span class="token function">is_empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">||</span> module <span class="token operator">==</span> <span class="token string">&quot;MODULE_UNSPECIFIED&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token class-name">Err</span><span class="token punctuation">(</span><span class="token string">&quot;module not allowed&quot;</span><span class="token punctuation">.</span><span class="token function">to_string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>按 <code>(路径模板, 方法)</code> 查接口表，<strong>查不到即拒绝</strong>——不是默认放行。新加的路由忘了登记，租户侧一律 403，生产环境不会替你兜底。fail-closed 的取向要大声说出来：开放系统的默认是&quot;没禁就允许&quot;，多租户系统的默认必须是&quot;没准就拒绝&quot;。</p><p>顺带一提，门前的免鉴权白名单同样是钉死的：8 个端点（登录、验证码、刷新令牌、MFA 挑战等）在 <code>auth_free.rs</code> 里逐一列出，守卫测试<strong>双向</strong>校验——公开路由集合必须恰好等于白名单，多一个少一个都不过。</p><h2 id="三、viewer-全仓唯一的租户判定点" tabindex="-1"><a class="header-anchor" href="#三、viewer-全仓唯一的租户判定点"><span>三、Viewer：全仓唯一的租户判定点</span></a></h2><p>数据层的隔离只有一个判定点。<code>Viewer</code> 是一个三态的小结构，每个仓储方法都收它，查询谓词由它派生：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/data/scope.rs</span></span>
<span class="line"><span class="token attribute attr-name">#[derive(Clone, Debug, Copy, PartialEq, Eq)]</span></span>
<span class="line"><span class="token keyword">pub</span> <span class="token keyword">enum</span> <span class="token type-definition class-name">ViewerKind</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/// No credentials (public routes).</span></span>
<span class="line">    <span class="token class-name">Noop</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">/// A verified user context: platform when tenant 0.</span></span>
<span class="line">    <span class="token class-name">User</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">/// Bypasses tenancy (seeds, internal jobs).</span></span>
<span class="line">    <span class="token class-name">System</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">pub</span> <span class="token keyword">fn</span> <span class="token function-definition function">tenant_scope</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Option</span><span class="token operator">&lt;</span><span class="token keyword">i64</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">match</span> <span class="token keyword">self</span><span class="token punctuation">.</span>kind <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">ViewerKind</span><span class="token punctuation">::</span><span class="token class-name">User</span> <span class="token keyword">if</span> <span class="token keyword">self</span><span class="token punctuation">.</span>tenant_id <span class="token operator">&gt;</span> <span class="token number">0</span> <span class="token operator">=&gt;</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token keyword">self</span><span class="token punctuation">.</span>tenant_id<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        _ <span class="token operator">=&gt;</span> <span class="token class-name">None</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/// Create stamping: tenant viewers force their tenant onto new rows.</span></span>
<span class="line"><span class="token keyword">pub</span> <span class="token keyword">fn</span> <span class="token function-definition function">stamp_tenant</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">,</span> requested<span class="token punctuation">:</span> <span class="token class-name">Option</span><span class="token operator">&lt;</span><span class="token keyword">i64</span><span class="token operator">&gt;</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Option</span><span class="token operator">&lt;</span><span class="token keyword">i64</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">match</span> <span class="token keyword">self</span><span class="token punctuation">.</span>kind <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">ViewerKind</span><span class="token punctuation">::</span><span class="token class-name">User</span> <span class="token keyword">if</span> <span class="token keyword">self</span><span class="token punctuation">.</span>tenant_id <span class="token operator">&gt;</span> <span class="token number">0</span> <span class="token operator">=&gt;</span> <span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token keyword">self</span><span class="token punctuation">.</span>tenant_id<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        _ <span class="token operator">=&gt;</span> requested<span class="token punctuation">.</span><span class="token function">or</span><span class="token punctuation">(</span><span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三态的语义边界：</p><ul><li><strong>租户视图</strong>（<code>User</code> 且 <code>tid &gt; 0</code>）：每次查询/更新/删除都约束 <code>tenant_id = tid</code>，建行强制盖章，跨租户写入被拒；</li><li><strong>平台视图</strong>（<code>User</code> 且 <code>tid == 0</code>）：不加租户谓词，所有租户的行全见；</li><li><strong>系统视图</strong>（<code>System</code>）：启动种子、内部作业等无凭据场景，旁路全部租户谓词。</li></ul><p>关键设计是**&quot;只有一处&quot;**：文件头自述它是 &quot;the standalone tenancy rule. there is exactly one place that decides tenancy filtering&quot;。租户判断不散落在各服务里，也就不存在&quot;某个服务忘了判&quot;这一类 bug——判断只可能写对一次，然后被所有仓储复用。</p><h2 id="四、repo-shell-谓词长在骨架上" tabindex="-1"><a class="header-anchor" href="#四、repo-shell-谓词长在骨架上"><span>四、repo_shell!：谓词长在骨架上</span></a></h2><p>判定点有了，怎么保证每个仓储方法都用它？答案是骨架宏：<code>repo_shell!</code> 生成的仓储结构自带谓词，业务代码拿到的查询<strong>天生</strong>带着隔离条件。</p><p><strong>租户臂</strong>——谓词是 <code>tenant_id</code> + 软删两连：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/data/repos/mod.rs</span></span>
<span class="line"><span class="token comment">/// The tenancy predicate: tenant viewers are constrained,</span></span>
<span class="line"><span class="token comment">/// platform/system viewers see all rows. Soft-deleted rows are</span></span>
<span class="line"><span class="token comment">/// invisible on every listing face ...</span></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">condition</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token namespace">sea_orm<span class="token punctuation">::</span></span><span class="token class-name">Condition</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">use</span> <span class="token namespace">sea_orm<span class="token punctuation">::</span></span><span class="token class-name">ColumnTrait</span> <span class="token keyword">as</span> _<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">match</span> <span class="token keyword">self</span><span class="token punctuation">.</span>viewer<span class="token punctuation">.</span><span class="token function">tenant_scope</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">Some</span><span class="token punctuation">(</span>tid<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token namespace">sea_orm<span class="token punctuation">::</span></span><span class="token class-name">Condition</span><span class="token punctuation">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$entity</span><span class="token punctuation">::</span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">TenantId</span><span class="token punctuation">.</span><span class="token function">eq</span><span class="token punctuation">(</span>tid<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$entity</span><span class="token punctuation">::</span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">DeletedAt</span><span class="token punctuation">.</span><span class="token function">is_null</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">None</span> <span class="token operator">=&gt;</span> <span class="token namespace">sea_orm<span class="token punctuation">::</span></span><span class="token class-name">Condition</span><span class="token punctuation">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$entity</span><span class="token punctuation">::</span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">DeletedAt</span><span class="token punctuation">.</span><span class="token function">is_null</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>全局臂</strong>给平台级表（无租户谓词，只铺软删）；<strong>名词臂</strong>在全局臂之上追加 <code>get_by_id</code>——查不到或已软删，一律 404。</p><p>一个值得驻足的细节：宏<strong>故意没有&quot;租户名词臂&quot;</strong>。文件头的原话：&quot;There is deliberately no tenant noun arm: a tenant-scoped get/delete must carry the viewer predicate, and those stay hand-written beside the invocation.&quot; 租户表的按 id 取行全部手写，因为它们必须显式携带 viewer 谓词——生成一个&quot;看起来方便&quot;的裸 <code>find_by_id</code> 正是要避免的事。手写的样子（<code>BiDashboardRepo::find_scoped</code>）：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/data/repos/bi_dashboard.rs</span></span>
<span class="line"><span class="token comment">/// The scoped row lookup — tenant viewers see own-tenant rows only,</span></span>
<span class="line"><span class="token comment">/// platform/system viewers any named row.</span></span>
<span class="line"><span class="token keyword">pub</span> <span class="token keyword">async</span> <span class="token keyword">fn</span> <span class="token function-definition function">find_scoped</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">,</span> id<span class="token punctuation">:</span> <span class="token keyword">i64</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token class-name">Option</span><span class="token operator">&lt;</span><span class="token namespace">entity<span class="token punctuation">::</span></span><span class="token class-name">Model</span><span class="token operator">&gt;</span><span class="token punctuation">,</span> <span class="token class-name">StatusError</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> <span class="token keyword">mut</span> query <span class="token operator">=</span> <span class="token namespace">entity<span class="token punctuation">::</span></span><span class="token class-name">Entity</span><span class="token punctuation">::</span><span class="token function">find_by_id</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token namespace">entity<span class="token punctuation">::</span></span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">DeletedAt</span><span class="token punctuation">.</span><span class="token function">is_null</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token keyword">let</span> <span class="token class-name">Some</span><span class="token punctuation">(</span>tid<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token keyword">self</span><span class="token punctuation">.</span>viewer<span class="token punctuation">.</span><span class="token function">tenant_scope</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        query <span class="token operator">=</span> query<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token namespace">entity<span class="token punctuation">::</span></span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">TenantId</span><span class="token punctuation">.</span><span class="token function">eq</span><span class="token punctuation">(</span>tid<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    query<span class="token punctuation">.</span><span class="token function">one</span><span class="token punctuation">(</span><span class="token keyword">self</span><span class="token punctuation">.</span>db<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token punctuation">.</span><span class="token function">map_err</span><span class="token punctuation">(</span>db_err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>写路径同构。create 的租户字段<strong>根本不读请求体</strong>，一律服务端盖章：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/data/repos/user.rs</span></span>
<span class="line"><span class="token keyword">let</span> tenant_id <span class="token operator">=</span> <span class="token keyword">self</span><span class="token punctuation">.</span>viewer<span class="token punctuation">.</span><span class="token function">stamp_tenant</span><span class="token punctuation">(</span><span class="token class-name">None</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token namespace">users<span class="token punctuation">::</span></span><span class="token class-name">ActiveModel</span> <span class="token punctuation">{</span></span>
<span class="line">    tenant_id<span class="token punctuation">:</span> <span class="token class-name">Set</span><span class="token punctuation">(</span>tenant_id<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">...</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>update / delete 的第一跳走 <code>find_scoped</code>——谓词叠在 <code>find_by_id</code> 上，别家的行、已软删的行，在&quot;取行&quot;这一步就 404。教程里把这写成一条陷阱清单：</p><blockquote><p><strong>服务里绕开仓储直接 <code>Entity::find_by_id(id)</code> 是唯一能造出越权读的写法——骨架方法全带谓词，裸查全不带。</strong></p></blockquote><p>隔离的完整闭环由此成形：读有骨架谓词、写有强制盖章、取行有作用域检查，唯一能绕过的是&quot;明知道规则还要绕&quot;——而那是代码审查的问题，不再是机制的问题。</p><h2 id="五、x-tenant-id-平台管理员的替身通道" tabindex="-1"><a class="header-anchor" href="#五、x-tenant-id-平台管理员的替身通道"><span>五、X-Tenant-Id：平台管理员的替身通道</span></a></h2><p>平台管理员（<code>tid = 0</code>）经常需要&quot;进入&quot;某个租户排查问题。这条通道做在门里，而不做在业务层：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/crates/auth/src/lib.rs</span></span>
<span class="line"><span class="token comment">// 代租户操作（\`X-Tenant-Id\`）：平台管理员可携带该头把本请求的生效</span></span>
<span class="line"><span class="token comment">// 租户切到所选租户——门对该租户跑完租户阶段（存在/启用/到期/套餐</span></span>
<span class="line"><span class="token comment">// 白名单，与租户成员同一标准），随后把 claims 的 tid 覆写为生效租户：</span></span>
<span class="line"><span class="token comment">// 下游 Viewer 的租户视图、建行的租户归属、/me 归属全部按所选租户行事，</span></span>
<span class="line"><span class="token comment">// 而 token 未动——审计里的 uid/tid 仍是真实操作者（平台侧）。头缺失</span></span>
<span class="line"><span class="token comment">// 即平台全域视图（现状）；租户成员携带该头一律忽略（其租户由 token</span></span>
<span class="line"><span class="token comment">// 决定）；非平台管理员（tid=0 但无 platform:admin 角色）同样忽略。</span></span>
<span class="line"><span class="token keyword">let</span> impersonated <span class="token operator">=</span> <span class="token keyword">if</span> token_tenant_id <span class="token operator">==</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span> is_platform_admin <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">parse_impersonated_tenant</span><span class="token punctuation">(</span></span>
<span class="line">        req<span class="token punctuation">.</span><span class="token function">headers</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;x-tenant-id&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">and_then</span><span class="token punctuation">(</span><span class="token closure-params"><span class="token closure-punctuation punctuation">|</span>v<span class="token closure-punctuation punctuation">|</span></span> v<span class="token punctuation">.</span><span class="token function">to_str</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ok</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">None</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> tenant_id <span class="token operator">=</span> impersonated<span class="token punctuation">.</span><span class="token function">unwrap_or</span><span class="token punctuation">(</span>token_tenant_id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三个值得抄走的决策：</p><ol><li><strong>替身也要过同一道租户阶段</strong>——平台管理员带 X-Tenant-Id 进入租户，走的检查与租户成员完全一致（存在/启用/到期/套餐白名单），&quot;管理员&quot;不是绕过检查的特权；</li><li><strong>token 不动，claims 覆写</strong>——生效租户只活在这一次请求里，签发的 JWT 保持原样；</li><li><strong>审计记真人</strong>——下游一切按替身租户行事，但审计日志里的操作者仍是平台侧真实账号。教程里的那句：&quot;<strong>审计答&#39;谁干的&#39;，业务行归属答&#39;给谁干的&#39;，两个问题两个来源。</strong>&quot;</li></ol><p>解析端从严：垃圾值不得变成另一个身份。<code>&quot;42&quot;</code>、<code>&quot; 7 &quot;</code> 生效；<code>&quot;0&quot;</code>、<code>&quot;-3&quot;</code>、<code>&quot;abc&quot;</code>、<code>&quot;1.5&quot;</code>、空串、缺失头全部不生效——单测逐值钉死。</p><h2 id="六、租户回收站-delete-是停车-不是删除" tabindex="-1"><a class="header-anchor" href="#六、租户回收站-delete-是停车-不是删除"><span>六、租户回收站：delete 是停车，不是删除</span></a></h2><p>租户删除走的不是 DELETE。删除动作把租户<strong>停车</strong>：级联清理 + 状态 OFF + 记下&quot;谁停的&quot;：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/tenant.rs</span></span>
<span class="line"><span class="token comment">// Cleanup semantics ride along: the tenants themselves are parked,</span></span>
<span class="line"><span class="token comment">// not deleted (module Delete → cleanup + OFF). deleted_by stamps the</span></span>
<span class="line"><span class="token comment">// operator so the recycle-bin face can show who parked it.</span></span>
<span class="line"><span class="token keyword">let</span> payload <span class="token operator">=</span> <span class="token function">operator_of</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>ctx<span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">self</span><span class="token punctuation">.</span><span class="token function">cleanup_rows</span><span class="token punctuation">(</span>row<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> <span class="token keyword">mut</span> a<span class="token punctuation">:</span> <span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>admin<span class="token punctuation">::</span>data<span class="token punctuation">::</span>sys_tenants<span class="token punctuation">::</span></span><span class="token class-name">ActiveModel</span> <span class="token operator">=</span> row<span class="token punctuation">.</span><span class="token function">into</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token punctuation">.</span>status <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;OFF&quot;</span><span class="token punctuation">.</span><span class="token function">into</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token punctuation">.</span>deleted_by <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">Some</span><span class="token punctuation">(</span>payload<span class="token punctuation">.</span>user_id<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token punctuation">.</span>deleted_at <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>admin<span class="token punctuation">::</span>data<span class="token punctuation">::</span></span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token punctuation">.</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">.</span>state<span class="token punctuation">.</span>db<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token punctuation">.</span><span class="token function">map_err</span><span class="token punctuation">(</span>db_err<span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>回收站三个 RPC，全部过平台管理员闸。</p><p><strong>列表</strong>：停车行按删除时间降序。在营面读 <code>deleted_at IS NULL</code>，回收站读 <code>is_not_null</code>——同一列两副面孔：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/data/repos/tenant.rs</span></span>
<span class="line"><span class="token comment">// 回收站：停车行（deleted_at 非空），删除时间降序</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token namespace">tenants<span class="token punctuation">::</span></span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">DeletedAt</span><span class="token punctuation">.</span><span class="token function">is_not_null</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">.</span><span class="token function">order_by_desc</span><span class="token punctuation">(</span><span class="token namespace">tenants<span class="token punctuation">::</span></span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">DeletedAt</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>教程对此的表述：&quot;<strong><code>is_not_null</code> 与在营面的 <code>is_null</code> 是同一列的两副面孔，互不可见；分页走同一条 <code>fetch_paged</code> 管线。</strong>&quot;</p><p><strong>恢复</strong>：先把&quot;在营域&quot;查重做完再动手——code 或 name 已被在营租户占用即拒绝；恢复成功也只是清掉盖戳、状态回 ON。文档诚实写明：<strong>恢复出来的是空壳</strong>——关联在删除时已清理，平台管理员恢复后需另行补建管理员。</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/tenant.rs</span></span>
<span class="line"><span class="token comment">// alive 域查重：code/name 被在营租户占用即拒绝（与 create 同文案）。</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token operator">!</span>row<span class="token punctuation">.</span>code<span class="token punctuation">.</span><span class="token function">is_empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> repo<span class="token punctuation">.</span><span class="token function">find_by_code</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>row<span class="token punctuation">.</span>code<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">.</span><span class="token function">is_some</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token class-name">Err</span><span class="token punctuation">(</span><span class="token function">status_error</span><span class="token punctuation">(</span><span class="token string">&quot;BAD_REQUEST&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;tenant already exists&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token operator">!</span>row<span class="token punctuation">.</span>name<span class="token punctuation">.</span><span class="token function">is_empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> repo<span class="token punctuation">.</span><span class="token function">find_by_name</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>row<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">.</span><span class="token function">is_some</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token class-name">Err</span><span class="token punctuation">(</span><span class="token function">status_error</span><span class="token punctuation">(</span><span class="token string">&quot;BAD_REQUEST&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;tenant already exists&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">let</span> <span class="token keyword">mut</span> a<span class="token punctuation">:</span> <span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>data<span class="token punctuation">::</span>sys_tenants<span class="token punctuation">::</span></span><span class="token class-name">ActiveModel</span> <span class="token operator">=</span> row<span class="token punctuation">.</span><span class="token function">into</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token punctuation">.</span>status <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">Some</span><span class="token punctuation">(</span><span class="token string">&quot;ON&quot;</span><span class="token punctuation">.</span><span class="token function">into</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token punctuation">.</span>deleted_at <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">None</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">a<span class="token punctuation">.</span>deleted_by <span class="token operator">=</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token class-name">None</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>彻底清除</strong>：再跑一遍级联清扫，然后物理删除。级联是一张 <code>wipe!</code> 宏展开的清单——40 张表逐一按 <code>tenant_id</code> 清除，含用户角色绑定、部门、角色、字典、审计表，以及 AI 提供商、BI 仪表盘、打印模板这些容易漏掉的跨域残余：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/services/tenant.rs</span></span>
<span class="line"><span class="token macro property">macro_rules!</span> wipe <span class="token punctuation">{</span></span>
<span class="line">    <span class="token punctuation">(</span>$<span class="token punctuation">(</span><span class="token variable">$entity</span><span class="token punctuation">:</span><span class="token fragment-specifier punctuation">ident</span><span class="token punctuation">)</span><span class="token punctuation">::</span><span class="token operator">+</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">        $<span class="token punctuation">(</span><span class="token variable">$entity</span><span class="token punctuation">)</span><span class="token punctuation">::</span><span class="token operator">+</span><span class="token punctuation">::</span><span class="token class-name">Entity</span><span class="token punctuation">::</span><span class="token function">delete_many</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span>$<span class="token punctuation">(</span><span class="token variable">$entity</span><span class="token punctuation">)</span><span class="token punctuation">::</span><span class="token operator">+</span><span class="token punctuation">::</span><span class="token class-name">Column</span><span class="token punctuation">::</span><span class="token class-name">TenantId</span><span class="token punctuation">.</span><span class="token function">eq</span><span class="token punctuation">(</span>tenant_id<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">exec</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">.</span>state<span class="token punctuation">.</span>db<span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token keyword">await</span></span>
<span class="line">            <span class="token punctuation">.</span><span class="token function">map_err</span><span class="token punctuation">(</span>db_err<span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token macro property">wipe!</span><span class="token punctuation">(</span>sys_user_roles<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// ……共 40 张表，含 6 张审计表收尾</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>审计层为回收站单设了动词——restore / purge 不落 <code>OTHER</code>：</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code><span class="line"><span class="token comment">// backend/apps/admin/src/admin/audit.rs</span></span>
<span class="line"><span class="token comment">// 回收站两动词：restore/purge 不落 OTHER。</span></span>
<span class="line"><span class="token string">&quot;RestoreTenant&quot;</span> <span class="token operator">=&gt;</span> <span class="token string">&quot;RESTORE&quot;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token string">&quot;PurgeTenant&quot;</span> <span class="token operator">=&gt;</span> <span class="token string">&quot;PURGE&quot;</span><span class="token punctuation">,</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>审计动词的颗粒度是排障效率的下限。<code>RESTORE</code> 和 <code>PURGE</code> 在日志里各自成行，&quot;谁在什么时候恢复了哪个租户、谁彻底清掉了哪个租户&quot;是一行查询的事；落成 <code>OTHER</code> 的日志排障时只能靠猜。</p><h2 id="七、机制-×-关键决策-×-失败模式" tabindex="-1"><a class="header-anchor" href="#七、机制-×-关键决策-×-失败模式"><span>七、机制 × 关键决策 × 失败模式</span></a></h2><table><thead><tr><th>机制</th><th>关键决策</th><th>失败模式（若无此决策）</th></tr></thead><tbody><tr><td>两道闸分层</td><td>HTTP 门管接口资格，数据层管行可见性</td><td>&quot;接口 403&quot;与&quot;列表为空&quot;混为一谈，排障无从下手</td></tr><tr><td>接口表 fail-closed</td><td>未注册的 (path, method) 一律拒绝</td><td>新路由默认放行，租户越权访问静默成型</td></tr><tr><td>Viewer 三态单点</td><td>全仓只有一个租户判定处</td><td>各服务各自判断，&quot;某个服务忘了判&quot;成整类 bug</td></tr><tr><td>repo_shell! 骨架谓词</td><td>租户臂/全局臂/名词臂自带谓词；无租户名词臂是故意的</td><td>裸 <code>find_by_id</code> 遍地开花，越权读只靠 review 拦</td></tr><tr><td>写路径盖章</td><td>create 不读请求体租户字段；update/delete 首跳 find_scoped</td><td>伪造 tenant_id 建行；跨租户 UPDATE/DELETE 落库</td></tr><tr><td>X-Tenant-Id 替身</td><td>同一租户阶段、token 不动、审计记真人</td><td>管理员通道绕过检查；审计丢失真实操作者</td></tr><tr><td>回收站停车</td><td>delete 级联 + OFF + deleted_by；恢复前 alive 域查重</td><td>误删租户不可逆；恢复后 code/name 撞车</td></tr><tr><td>purge 全域级联</td><td>40 表清单含跨域残余（AI/BI/打印）</td><td>孤儿行挂在别家表里，泄漏已删租户数据</td></tr></tbody></table><p>多租户隔离的成熟度，不看宣传页上的&quot;支持多租户&quot;，看三件事：<strong>判定点是不是只有一个、绕过骨架是不是比走骨架更难、误删之后还有没有退路</strong>。RushWind Admin 把第一件做成一个 85 行的文件，第二件做成一个故意少一条臂的宏，第三件做成一座回收站——机制的边界画在哪里，事故的边界就在哪里。</p><hr><p>项目地址：<a href="https://gitee.com/tx7do/rushwind-admin" target="_blank" rel="noopener noreferrer">Gitee</a> ｜ <a href="https://github.com/tx7do/rushwind-admin" target="_blank" rel="noopener noreferrer">GitHub</a></p><p>系列文章：</p><ul><li>上一篇：<a href="https://tx7do.github.io/posts/rushwind_admin_update_mask.html" target="_blank" rel="noopener noreferrer">update_mask 写面：字段级白名单、显式清除与点路径合并</a></li><li>下一篇：<a href="https://tx7do.github.io/posts/rushwind_cms_three_service_topology.html" target="_blank" rel="noopener noreferrer">RushWind CMS — 三服务拓扑：core 领域层、双 BFF 薄代理与一份契约的双面输出</a></li></ul>`,60)])])}const i=s(e,[["render",o]]),u=JSON.parse('{"path":"/posts/rushwind_admin_tenant_recycle_bin.html","title":"RushWind Admin — 多租户行级隔离与租户回收站：Viewer 三态、repo_shell! 与全域级联清除","lang":"zh-CN","frontmatter":{"date":"2026-11-20T00:00:00.000Z","category":["Rust编程"],"tag":["Rust","RushWind","多租户","数据权限"],"sticky":10},"headers":[{"level":2,"title":"一、两道闸：HTTP 门与数据层谓词","slug":"一、两道闸-http-门与数据层谓词","link":"#一、两道闸-http-门与数据层谓词","children":[]},{"level":2,"title":"二、HTTP 门：租户阶段夹在认证与授权之间","slug":"二、http-门-租户阶段夹在认证与授权之间","link":"#二、http-门-租户阶段夹在认证与授权之间","children":[]},{"level":2,"title":"三、Viewer：全仓唯一的租户判定点","slug":"三、viewer-全仓唯一的租户判定点","link":"#三、viewer-全仓唯一的租户判定点","children":[]},{"level":2,"title":"四、repo_shell!：谓词长在骨架上","slug":"四、repo-shell-谓词长在骨架上","link":"#四、repo-shell-谓词长在骨架上","children":[]},{"level":2,"title":"五、X-Tenant-Id：平台管理员的替身通道","slug":"五、x-tenant-id-平台管理员的替身通道","link":"#五、x-tenant-id-平台管理员的替身通道","children":[]},{"level":2,"title":"六、租户回收站：delete 是停车，不是删除","slug":"六、租户回收站-delete-是停车-不是删除","link":"#六、租户回收站-delete-是停车-不是删除","children":[]},{"level":2,"title":"七、机制 × 关键决策 × 失败模式","slug":"七、机制-×-关键决策-×-失败模式","link":"#七、机制-×-关键决策-×-失败模式","children":[]}],"git":{"updatedTime":1795150321000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":2,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"db72b04d7557f847e20325b35e03eff3e1a9bd4e","time":1795150321000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: update posts."},{"hash":"16d3c4973313d13612d77376cd8e8b96b7c18718","time":1795147039000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/rushwind_admin_tenant_recycle_bin.md","excerpt":"\\n<blockquote>\\n<p>本文回答一个问题：<strong>一个列表查询怎么做到「想查出别家租户的行都漏不掉」？租户被删之后数据去哪了、恢复时凭什么不撞名、彻底清除时怎么不留下孤儿行？</strong></p>\\n</blockquote>\\n<p>多租户系统最怕的不是没有隔离，而是\\"靠每个开发者记得加租户条件\\"的隔离——新人一个 <code>find_by_id</code> 没带谓词，别家的数据就顺着接口流出去，而且没有人知道。<a href=\\"https://github.com/tx7do/rushwind-admin\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">RushWind Admin</a> 把隔离做成两层结构：HTTP 门负责\\"这个租户能不能用这个接口\\"，数据层谓词负责\\"这个查询能不能看见那行数据\\"。删除则更进一步——<strong>delete 不是删除，是停车</strong>。本文把这两层和一条回收站链路全部拆开。</p>"}');export{i as comp,u as data};
